ee:message.ee:set-payload:
%dw 2.0 output application/json
var resolvedErrorType = if ((error.suppressedErrors.errorType[0] default null) != null) error.suppressedErrors.errorType[0].namespace ++ ":" ++ error.suppressedErrors.errorType[0].identifier else error.errorType.namespace ++ ":" ++ error.errorType.identifier
--- { status: "FAILED", errorType: resolvedErrorType, message: if (resolvedErrorType == "DB:CONNECTIVITY") "Database connectivity failed" else if (resolvedErrorType == "DB:BAD_SQL_SYNTAX") "Invalid SQL syntax" else if (resolvedErrorType == "DB:QUERY_EXECUTION") "Database query execution failed" else "Unknown error", timestamp: now() as String }

db:select.db:input-parameters:
#[{
    'offset' : vars.currentOffset as Number,
    'limit' : vars.limit as Number
}]

ee:message.ee:set-payload:
%dw 2.0 output application/json
var resolvedErrorType = if ((error.suppressedErrors.errorType[0] default null) != null) error.suppressedErrors.errorType[0].namespace ++ ":" ++ error.suppressedErrors.errorType[0].identifier else error.errorType.namespace ++ ":" ++ error.errorType.identifier
--- { status: "FAILED", errorType: resolvedErrorType, message: if (resolvedErrorType == "DB:CONNECTIVITY") "Database connectivity failed" else if (resolvedErrorType == "DB:BAD_SQL_SYNTAX") "Invalid SQL syntax" else if (resolvedErrorType == "DB:QUERY_EXECUTION") "Database query execution failed" else "Unknown error", timestamp: now() as String }

ee:variables.ee:set-variable:
%dw 2.0 output application/java
var cutOffDate = |2026-05-03|
var transformedBatch = (payload default []) map (employee) -> { "Name": trim((employee.first_name default "") ++ " " ++ (employee.last_name default "")), "DOJ": if (employee.date_of_joining != null) (employee.date_of_joining as Date {format: "yyyy-MM-dd"}) else null, "Email ID": if (!isEmpty(employee.email_id)) employee.email_id else "N/A" }
var filteredBatch = transformedBatch filter ((item) -> item.DOJ != null and (item.DOJ > cutOffDate) )
---
vars.accumulator ++ (filteredBatch map (item) -> { "FullName": item.Name, "DOJ": item.DOJ as String {format: "dd-MM-yyyy"}, "Email ID": item."Email ID" })
